package entity;

/** Represents a row of the "usuario" (library user) table. */
public class Usuario {

    private int id;
    private String nome;
    private String email;

    public Usuario() {
    }

    // Convenient constructor for a new user (the id is generated by the database).
    public Usuario(String nome, String email) {
        this.nome = nome;
        this.email = email;
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getNome() {
        return nome;
    }

    public void setNome(String nome) {
        this.nome = nome;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    @Override
    public String toString() {
        return "Usuario{id=" + id
                + ", nome='" + nome + '\''
                + ", email='" + email + '\'' + '}';
    }
}
